import {calcField as field,calcSelect as select,calcCheck as check,calcDisclosure as details,calcEscape as esc,calcParentLabel} from './calculator-view.js';
import {CALCULATOR_LABELS} from './calculator-engine.js';
const occupationOptions=[['employee','Umowa o pracę'],['contract','Zlecenie / inny tytuł niepracowniczy'],['business','Działalność gospodarcza'],['uninsured','Brak tytułu chorobowego ZUS'],['startup','Ulga na start'],['student','Student do 26 lat — samo zlecenie'],['work','Umowa o dzieło poza własnym pracodawcą'],['unregistered','Działalność nierejestrowa'],['krus','KRUS — bez odrębnego tytułu ZUS']];
export function calculatorSituationHtml(input){return `<section class="calc-section"><h2>Co chcecie sprawdzić?</h2><p>Wybierzcie zakres, a pozostałe pytania dopasujemy do Waszej sytuacji. Wszystkie wyliczenia pozostają w tym kalkulatorze.</p><div class="calc-options">${Object.entries(CALCULATOR_LABELS).map(([id,label])=>`<button type="button" data-calc-focus="${id}" aria-pressed="${input.focus===id}" class="${input.focus===id?'selected':''}"><strong>${label}</strong><small>${{family:'Długość, kwoty, podział rodziców i powrót do pracy',sickness:'Ubezpieczenie, wyczekiwanie i dni wypłaty',rehab:'Dalsza niezdolność, decyzja i waloryzacja',prebirth:'Szczególne przypadki ustania zatrudnienia',care:'Limity wspólne dla rodziny i stawka 80%',business:'Ulga na start, preferencje i Mały ZUS Plus'}[id]}</small></button>`).join('')}</div><div class="calc-fields">${select(input,'familyType','Sytuacja rodzinna',[['unknown','Nie ustalono — wybierz właściwą sytuację'],['birth','Ciąża / urodzenie dziecka'],['adoption','Przyjęcie i wniosek o przysposobienie'],['foster','Niezawodowa / spokrewniona rodzina zastępcza'],['professional','Zawodowa rodzina zastępcza']])}${select(input,'dateKind','Podana data jest',[['expected','Planowana'],['actual','Rzeczywista']])}${field(input,'eventDate',input.focus==='business'?'Data odniesienia dla składek':input.focus==='sickness'?'Pierwszy dzień niezdolności':input.focus==='rehab'?'Początek świadczenia rehabilitacyjnego':input.focus==='care'?'Początek opieki':input.familyType==='birth'?'Data porodu lub planowanego porodu':'Data przyjęcia i spełnienia warunków',{type:'date',required:true,help:'Podaj datę zdarzenia właściwego dla tego zakresu. Zapis scenariusza zachowuje osobne dane profilu.'})}${field(input,'count','Dzieci przy jednym porodzie / jednoczesnym przyjęciu',{step:1,min:1,max:12})}${input.focus==='care'?field(input,'childBirthDate','Data urodzenia dziecka — wymagana dla dodatkowej opieki',{type:'date'}):''}${['adoption','foster','professional'].includes(input.familyType)&&input.focus==='family'?select(input,'primaryParent','Opiekun rozpoczynający okres na warunkach macierzyńskiego',[[0,'Rodzic / opiekun 1'],[1,'Rodzic / opiekun 2']])+field(input,'childBirthDate','Data urodzenia przyjmowanego dziecka',{type:'date',required:true})+(input.familyType==='adoption'?field(input,'adoptionApplicationDate','Data wystąpienia do sądu o przysposobienie',{type:'date'})+field(input,'adoptionCourtDate','Prawomocność przysposobienia — dla ojcowskiego',{type:'date'}):'')+check(input,'schoolDelayed','Prawomocnie odroczony obowiązek szkolny'):''}</div>${['adoption','foster'].includes(input.familyType)&&input.focus==='family'&&input.count>1?check(input,'adoptionDifferentAges','Dzieci przyjmowane jednocześnie mają różne daty urodzenia')+field(input,'adoptionVerifiedDays','Dni na warunkach macierzyńskiego ustalone przez płatnika dla różnego wieku dzieci',{step:1,max:259,help:'Przy różnym wieku potrzebne jest indywidualne ustalenie puli. Data powyżej dotyczy najstarszego dziecka; nie zakładamy wspólnych urodzin.'}):''}${check(input,'life','Dziecko ma zaświadczenie „Za życiem”','Chodzi o zaświadczenie ustawowe, nie o każde orzeczenie o niepełnosprawności.')}</section>`;}
function titleFields(input,prefix){
  const title=prefix.split('.').reduce((o,k)=>o?.[k],input),employee=title.occupation==='employee',business=title.occupation==='business';
  const modes=[['known','Mam podstawę ustaloną przez płatnika / ZUS'],...(employee?[['salary','Stała pensja — typowe potrącenie 13,71%'],['history','Historia miesięcznych wynagrodzeń']]:[['business-history','Historia podstaw składek chorobowych']]),['first-month','Pierwszy niepełny miesiąc']];
  const mode=modes.some(([key])=>key===title.basisMode)?title.basisMode:'known';
  return `<div class="calc-fields">${select(input,prefix+'.occupation','Tytuł ubezpieczenia',occupationOptions)}${select(input,prefix+'.coverage','Ubezpieczenie chorobowe',[['unknown','Nie wiem — sprawdzę'],['compulsory','Obowiązkowe'],['voluntary','Dobrowolne'],['none','Brak chorobowego']])}${field(input,prefix+'.insuranceFrom','Początek ubezpieczenia',{type:'date'})}${field(input,prefix+'.insuranceTo','Koniec zatrudnienia / ubezpieczenia, jeśli znany',{type:'date'})}${select(input,prefix+'.basisMode','Jak ustalić podstawę?',modes)}</div>
    ${mode==='known'?field(input,prefix+'.basis','Miesięczna podstawa wymiaru zasiłku po potrąceniach (zł)',{min:.01,step:.01,placeholder:'Np. podstawa z informacji płatnika',help:'To nie jest pensja netto. Przy świadczeniu po ustaniu uwzględnij właściwe ograniczenie podstawy.'}):mode==='salary'||mode==='first-month'&&!business?`<div class="calc-fields">${field(input,prefix+'.salary','Stałe wynagrodzenie brutto (zł)',{min:.01,step:.01})}${field(input,prefix+'.monthlyBonus','Uwzględniany składnik miesięczny (zł)',{step:.01})}</div><p class="field-help">Uproszczenie zakłada typowe potrącenia. Wybierz historię, jeżeli wynagrodzenie było zmienne lub występowały absencje.</p>`:mode==='first-month'&&business?field(input,prefix+'.minimumBasis','Najniższa miesięczna podstawa składek właściwa dla JDG (zł)',{step:.01,help:'Bez wcześniejszego tytułu podstawą jest właściwe minimum po odliczeniu 13,71%. Nietypowe przejście z innego tytułu wymaga ustalenia przez ZUS.'}):`<div class="calc-history"><p>Wprowadź pełne miesiące przed miesiącem świadczenia, u właściwego płatnika. Dla JDG wpisuj podstawy składek, a nie przychody z faktur.</p><div class="calc-table-scroll"><table><thead><tr><th>Miesiąc</th><th>${business?'Podstawa składek':'Brutto'}</th>${employee?'<th>Potrącone składki</th>':'<th>Minimum podstawy</th>'}<th>Dni pracy / działalności</th><th>Dni wymagane</th></tr></thead><tbody>${(title.history||[]).map((row,index)=>`<tr><td>${index+1}</td><td><input aria-label="Kwota miesiąca ${index+1}" type="number" min="0" step=".01" data-calc-field="${prefix}.history.${index}.gross" value="${row.gross??''}"></td><td><input aria-label="${employee?'Potrącenia':'Minimum'} miesiąca ${index+1}" type="number" min="0" step=".01" data-calc-field="${prefix}.history.${index}.${employee?'deducted':'minimum'}" value="${employee?row.deducted??'':row.minimum??''}"></td><td><input aria-label="Dni przepracowane miesiąca ${index+1}" type="number" min="0" max="31" data-calc-field="${prefix}.history.${index}.worked" value="${row.worked??20}"></td><td><input aria-label="Dni wymagane miesiąca ${index+1}" type="number" min="1" max="31" data-calc-field="${prefix}.history.${index}.scheduled" value="${row.scheduled??20}"></td></tr>`).join('')}</tbody></table></div><button type="button" class="secondary" data-add-history="${prefix}">Dodaj miesiąc (maks. 12)</button></div>`}
    ${details('Nietypowe wynagrodzenie i wcześniejsza podstawa',`<div class="calc-fields">${field(input,prefix+'.quarterBonuses','Suma uwzględnianych premii z 4 kwartałów (zł)',{step:.01})}${field(input,prefix+'.annualBonus','Uwzględniana premia za poprzedni rok (zł)',{step:.01})}${field(input,prefix+'.benefitRetainedComponents','Składniki wypłacane mimo świadczenia — do wyłączenia (zł)',{step:.01})}${field(input,prefix+'.previousBasis','Wcześniej ustalona podstawa (zł)',{step:.01})}${field(input,prefix+'.minimumBasis','Minimum podstawy składek w krótkim ubezpieczeniu (zł)',{step:.01})}${field(input,prefix+'.declaredBasis','Uzupełniona do pełnego miesiąca podstawa deklarowana — art. 49 (zł)',{step:.01})}${field(input,prefix+'.contractMonthly','Miesięczna kwota umowna zlecenia — pierwszy miesiąc (zł)',{step:.01})}${field(input,prefix+'.priorTitleMonths','Pełne miesiące wcześniejszego tytułu (do 12)',{step:1,max:12})}</div>${check(input,prefix+'.completedMonthBasis','Podana podstawa deklarowana została prawidłowo uzupełniona do pełnego miesiąca')}${check(input,prefix+'.basisContinuous','Zachowana podstawa — brak przerwy lub przerwa krótsza niż miesiąc kalendarzowy')}${check(input,prefix+'.fteChanged','W okresie bazowym zmienił się etat — podane dane dotyczą już nowego wymiaru')}`)}
    ${details('Koniec umowy, wyczekiwanie i szczególne okoliczności',`<div class="calc-fields">${select(input,prefix+'.endReason','Przyczyna ustania',[['none','Nie ustało'],['ordinary','Zwykły koniec umowy / działalności'],['bankruptcy','Upadłość pracodawcy'],['liquidation','Likwidacja pracodawcy'],['employer-death','Śmierć pracodawcy'],['court','Bezprawne rozwiązanie potwierdzane przez sąd'],['extended-birth','Umowa przedłużona do dnia porodu']])}${select(input,prefix+'.waitException','Wyjątek od wyczekiwania / zaliczenie okresów',[['none','Brak wyjątku'],['graduate','Absolwent — ubezpieczenie w ustawowym terminie'],['ten-years','Co najmniej 10 lat obowiązkowego chorobowego'],['commute','Wypadek w drodze do pracy lub z pracy'],['protected-gap','Ustawowo zaliczana dłuższa przerwa']])}${field(input,prefix+'.previousDays','Zaliczane dni wcześniejszego ubezpieczenia',{step:1})}${field(input,prefix+'.previousGap','Dni przerwy między tytułami',{step:1})}${field(input,prefix+'.debt','Dług składkowy na dzień prawa do świadczenia (zł)',{step:.01})}${field(input,prefix+'.debtPaidDate','Data pełnej spłaty, jeśli nastąpiła',{type:'date'})}</div>${check(input,prefix+'.installmentAgreement','Obowiązuje umowa ratalna lub odroczenie z ZUS')}${check(input,prefix+'.installmentsTimely','Umowa jest realizowana terminowo')}${check(input,prefix+'.noDebtOutsideAgreement','Nie ma zadłużenia poza umową')}${check(input,prefix+'.courtConfirmed','Mam prawomocne orzeczenie o bezprawnym rozwiązaniu')}${check(input,prefix+'.parentalLeave','Poród / przyjęcie następuje podczas urlopu wychowawczego')}${check(input,prefix+'.otherEmploymentOffered','Zapewniono inne zatrudnienie po szczególnej utracie pracy')}${check(input,prefix+'.externalExclusion','Występuje ustawowe wyłączenie po ustaniu, np. inne wskazane świadczenie lub obowiązkowy KRUS')}${check(input,prefix+'.unpaidLeave','Okres niezdolności przypada na urlop bezpłatny / inny okres bez prawa do zwykłego chorobowego')}`)}
  `;
}
export function calculatorParentsHtml(input){
  const count=['family','care'].includes(input.focus)?2:1;
  return `<section class="calc-section"><h2>Ubezpieczenie i podstawa świadczenia</h2><p>Podstawa każdego rodzica jest odrębna. Nie musicie znać wszystkich danych od razu — brakujące wartości zostaną wskazane w wyniku.</p><div class="calc-parent-forms">${input.parents.slice(0,count).map((parent,index)=>`<section class="calc-parent-form"><h3>${calcParentLabel(input,index)}</h3>${titleFields(input,'parents.'+index)}<div class="calc-fields">${field(input,'parents.'+index+'.fte','Pierwotny wymiar etatu',{min:.01,max:1,step:.01,help:'1 = pełny etat; 0,5 = połowa. Potrzebne przy łączeniu z pracą.'})}${field(input,'parents.'+index+'.birthDate','Data urodzenia rodzica — dla limitu 33/14 dni',{type:'date'})}${select(input,'parents.'+index+'.payer','Kto wypłaca zasiłki?',[['unknown','Nie wiem — wskaż właściwą drogę'],['employer','Uprawniony płatnik składek'],['zus','ZUS']])}</div>${(parent.extraTitles||[]).map((t,j)=>details('Dodatkowy tytuł '+(j+2),titleFields(input,'parents.'+index+'.extraTitles.'+j))).join('')}<button type="button" class="secondary" data-add-title="${index}">Dodaj kolejny tytuł ubezpieczenia</button></section>`).join('')}</div></section>`;
}
export function calculatorPlanHtml(input,rules){
  const limits=rules?.parameters?.limits||{reserved:9,prenatal:42,parentalParts:5},rates=rules?.parameters?.rates||{maternity:100,parental:70,averaged:81.5};
  if(input.focus==='business')return businessHtml(input);
  if(input.focus==='care')return careHtml(input);
  if(input.focus!=='family')return sicknessHtml(input);
  const birth=input.familyType==='birth';
  return `<section class="calc-section"><h2>Jak chcecie podzielić opiekę?</h2><div class="calc-fields">${select(input,'rateChoice','Wariant wypłaty',[['standard',rates.maternity.toLocaleString('pl-PL')+'% macierzyński i '+rates.parental.toLocaleString('pl-PL')+'% rodzicielski'],['averaged',rates.averaged.toLocaleString('pl-PL')+'% po terminowym wniosku']])}${field(input,'applicationDate','Data wniosku o wariant uśredniony',{type:'date',help:'Przy dacie planowanej porównujemy przyszły wariant. Właściwy termin to 21 dni po zdarzeniu.'})}${birth?field(input,'prenatalDays','Macierzyński przed porodem — dni',{max:limits.prenatal,step:1}):''}</div><p>Rodzicielski ma wspólną pulę i po ${limits.reserved} tygodni wyłącznie dla każdego rodzica. Możecie dodać części, wybrać daty równoległe albo naprzemienne oraz pracę u pracodawcy udzielającego urlopu.</p><div class="calc-parts">${input.parentalParts.map((part,index)=>`<fieldset><legend>Część ${index+1}</legend><div class="calc-fields">${select(input,'parentalParts.'+index+'.parent','Kto korzysta?',[[0,calcParentLabel(input,0)],[1,calcParentLabel(input,1)]])}${field(input,'parentalParts.'+index+'.weeks','Tygodnie z pierwotnej puli',{step:1,max:150})}${field(input,'parentalParts.'+index+'.start','Początek — puste: po poprzednim okresie tego rodzica',{type:'date'})}${field(input,'parentalParts.'+index+'.work','Praca podczas tej części — ułamek pełnego etatu',{max:.5,step:.01,help:'0 = bez pracy; najwyżej 0,5 pełnego etatu.'})}${field(input,'parentalParts.'+index+'.extensionWork','Praca w powstałym wydłużeniu — ułamek pełnego etatu',{max:.5,step:.01})}</div><button type="button" class="text-button" data-remove-part="${index}">Usuń część</button></fieldset>`).join('')}</div><button type="button" class="secondary" id="calc-add-part">Dodaj część rodzicielskiego</button><div class="calc-fields">${field(input,'paternityDays','Ojcowski — 0, 7 lub 14 dni',{step:7,max:14})}${field(input,'paternityStart','Początek ojcowskiego',{type:'date'})}${field(input,'paternitySecondStart','Druga część ojcowskiego, jeśli dzielicie 14 dni',{type:'date'})}</div>
  ${details('Wcześniejsze wykorzystanie na to dziecko',`<div class="calc-fields">${field(input,'previousMaternityDays','Wykorzystane dni na warunkach macierzyńskiego — piecza/adopcja',{step:1})}${field(input,'previousParent1Days','Rodzic 1 — wykorzystane dni rodzicielskiego',{step:1})}${field(input,'previousParent2Days','Rodzic 2 — wykorzystane dni rodzicielskiego',{step:1})}${field(input,'previousParts','Liczba wykorzystanych części obojga rodziców',{step:1,max:5})}</div><p class="field-help">Przy późniejszej adopcji po pieczy nie powstaje od nowa cała pula na to samo dziecko.</p>`)}
  ${details('Wcześniak lub hospitalizacja dziecka',`<p>Podaj ukończone tygodnie ciąży z zaświadczenia oraz najniższą masę przy porodzie mnogim. Pobyt każdego dziecka zapisuj osobno. Dzień porodu jest pierwszą dobą osi czasu.</p><div class="calc-fields">${field(input,'gestation','Ukończone tygodnie ciąży przy porodzie',{min:20,max:44,step:.01})}${field(input,'birthWeight','Najniższa masa urodzeniowa (g)',{min:100,max:10000,step:1})}${select(input,'supplementParent','Kto korzysta z uzupełniającego?',[[0,calcParentLabel(input,0)],[1,calcParentLabel(input,1)]])}${field(input,'supplementApplication','Data wniosku o uzupełniający, jeśli złożono',{type:'date'})}</div>${input.hospitals.map((stay,index)=>`<div class="calc-hospital"><div class="calc-fields">${field(input,'hospitals.'+index+'.child','Numer dziecka',{min:1,max:input.count,step:1})}${field(input,'hospitals.'+index+'.start','Przyjęcie do szpitala',{type:'date'})}${field(input,'hospitals.'+index+'.end','Wypis ze szpitala',{type:'date'})}</div><button type="button" class="text-button" data-remove-hospital="${index}">Usuń pobyt</button></div>`).join('')}<button type="button" class="secondary" id="calc-add-hospital">Dodaj pobyt w szpitalu</button>`)}
  ${details('Przejęcie opieki lub przerwa w macierzyńskim',`<div class="calc-fields">${select(input,'transfer','Przejęcie przez ojca / bliskiego',[['none','Bez przejęcia'],['ordinary','Rezygnacja uprawnionej matki po minimum 14 tygodniach'],['mother-hospital','Szpital uprawnionej matki — przerwanie po 8 tygodniach'],['mother-incapacity','Orzeczona niesamodzielność matki'],['mother-death','Śmierć matki'],['abandonment','Porzucenie przez matkę'],['mother-employed','Nieubezpieczona matka podejmuje pracę co najmniej 1/2 etatu']])}${field(input,'motherPostWeeks','Tygodnie matki po porodzie przed zwykłym przekazaniem',{step:1,max:100})}${field(input,'transferDate','Data zdarzenia / przerwania opieki',{type:'date'})}${field(input,'transferEnd','Koniec czasowego przejęcia, jeśli znany',{type:'date'})}</div>${check(input,'otherParentStopsWork','Niepracownik przejmujący opiekę przerywa działalność zarobkową dla osobistej opieki')}<p>Odrębnie: przerwa macierzyńskiego po 8 tygodniach z powodu szpitala dziecka (przesuwa pozostałą pulę; nie dodaje jej drugi raz).</p><div class="calc-fields">${field(input,'motherPauseStart','Początek przerwy — szpital dziecka',{type:'date'})}${field(input,'motherPauseEnd','Koniec przerwy / wypis dziecka',{type:'date'})}</div>`)}
  ${details('Strata dziecka lub szczególna zmiana opieki',`<p>Możecie sprawdzić formalności bez podawania płci dziecka. W takich sprawach pokażemy także bezpłatne wsparcie organizacji charytatywnych.</p><div class="calc-fields">${select(input,'loss','Sytuacja',[['none','Nie dotyczy'],['stillbirth','Martwe urodzenie / strata ciąży'],['child-death','Śmierć dziecka po porodzie'],['child-care-placement','Utrata osobistej opieki / umieszczenie w pieczy']])}${field(input,'lossDate','Data zdarzenia, jeśli po porodzie',{type:'date'})}${field(input,'surviving','Dzieci pozostające przy życiu z tego porodu',{step:1,max:input.count})}</div>`)}
  ${details('Podwyższenie do świadczenia rodzicielskiego',`<p>Potrzebna jest rzeczywista łączna kwota po zaliczce PIT z wszystkich tytułów tego samego rodzica w wybranym miesiącu. Nie obliczamy jej z samego brutto.</p><div class="calc-fields">${field(input,'topUpMonth','Miesiąc do sprawdzenia',{type:'month'})}${field(input,'netReceived1','Matka / opiekun 1 — łączna kwota netto po PIT (zł)',{step:.01})}${field(input,'netReceived2','Ojciec / opiekun 2 — łączna kwota netto po PIT (zł)',{step:.01})}</div>`)}
  </section>`;
}
function sicknessHtml(input){const rehab=input.focus==='rehab';return `<section class="calc-section"><h2>${rehab?'Plan rehabilitacji i decyzja':'Okres niezdolności do pracy'}</h2><div class="calc-fields">${field(input,'sickness.start','Pierwszy dzień okresu',{type:'date'})}${field(input,'sickness.days','Liczba dni do sprawdzenia',{step:1,max:730})}${field(input,'sickness.usedDays','Wcześniej wykorzystane dni obecnego okresu zasiłkowego',{step:1,max:730})}${field(input,'sickness.usedEmployerDays','Wykorzystane dni wynagrodzenia chorobowego w roku',{step:1,max:366})}${field(input,'sickness.usedAfterEndDays','Wykorzystane dni zwykłego chorobowego po ustaniu — limit 91 dni',{step:1,max:91})}${field(input,'sickness.previousEnd','Koniec poprzedniej niezdolności, jeśli była przerwa',{type:'date'})}${select(input,'sickness.certificate','Niezdolność potwierdzona e-ZLA / właściwym dokumentem',[['unknown','Jeszcze nie wiem / nie wystawiono'],['yes','Tak; ciąża potwierdzona kodem B lub osobno'],['no','Nie']])}</div>${check(input,'sickness.pregnant','Okres przypada w czasie ciąży')}${check(input,'sickness.otherBenefit','Występuje inne ustawowo wyłączające świadczenie, np. emerytura, renta lub wskazane świadczenie dla bezrobotnych')}${check(input,'sickness.workingDuring','Występuje praca zarobkowa lub aktywność wymagająca oceny zgodności ze zwolnieniem')}${rehab?check(input,'sickness.rehabExhausted','Wyczerpano okres zasiłku chorobowego')+check(input,'sickness.prognosis','Dalsze leczenie rokuje odzyskanie zdolności do pracy')+check(input,'sickness.rehabGranted','ZUS przyznał już wskazany okres rehabilitacyjnego')+check(input,'sickness.rehabAlreadyIndexed','Podana podstawa rehabilitacyjnego jest już zwaloryzowana'):''}<p class="field-help">Sama ciąża nie powoduje niezdolności do pracy. Rzeczywisty stan medyczny i okres potwierdza uprawniona osoba.</p></section>`;}
function careHtml(input){return `<section class="calc-section"><h2>Opieka i wykorzystany limit</h2><div class="calc-fields">${select(input,'care.parent','Kto będzie sprawować opiekę?',[[0,calcParentLabel(input,0)],[1,calcParentLabel(input,1)]])}${select(input,'care.type','Rodzaj opieki',[['sick-child','Chore dziecko'],['healthy-child','Zdrowe dziecko poniżej 8 lat — ustawowe zdarzenie'],['disabled-child','Dziecko z niepełnosprawnością'],['adult','Inny chory członek rodziny'],['extra-newborn','Dodatkowa opieka w szczególnej sytuacji pierwszych 8 tygodni']])}${field(input,'care.start','Początek opieki',{type:'date'})}${field(input,'care.days','Potrzebne dni',{step:1,max:365})}${field(input,'care.ageMonths','Ukończone miesiące życia dziecka',{step:1})}${select(input,'care.reason','Powód opieki nad zdrowym dzieckiem',[['closure','Nieprzewidziane zamknięcie placówki'],['carer-illness','Choroba / poród stałego opiekuna'],['carer-hospital','Szpital stałego opiekuna'],['other','Inna ustawowa przesłanka — do potwierdzenia']])}${field(input,'care.closureNotice','Przy zamknięciu placówki: ile dni wcześniej zawiadomiono?',{step:1})}${field(input,'care.usedAll','Wykorzystane wspólnie dni opiekuńczego w roku',{step:1})}${field(input,'care.usedDisabled','W tym dni opieki z podlimitu 30',{step:1})}${field(input,'care.usedAdult','W tym dni z podlimitu 14',{step:1})}</div>${check(input,'care.sameHousehold','Przy opiece nad chorym dorosłym: wspólne gospodarstwo domowe w okresie opieki')}${check(input,'care.noOtherCarer','Nie ma zdolnego domownika mogącego zapewnić opiekę')}${check(input,'care.qualifyingReason','Spełniony jest ustawowy powód opieki nad zdrowym dzieckiem lub szczególny powód dodatkowej opieki')}${check(input,'care.disabled','Dziecko ma wymagane orzeczenie i wskazania')}${check(input,'care.onlyOlderDisabled','Rodzina korzysta wyłącznie z opieki nad starszym niepełnosprawnym dzieckiem i innymi chorymi członkami rodziny — łączna pula 30 dni')}</section>`;}
function businessHtml(input){return `<section class="calc-section"><h2>Działalność i ulgi składkowe</h2><div class="calc-fields">${field(input,'business.start','Rozpoczęcie działalności',{type:'date'})}${field(input,'business.previousEnd','Ostatnie zakończenie / zawieszenie wcześniejszej działalności',{type:'date'})}${field(input,'business.previousYearDays','Dni działalności w poprzednim roku',{step:1,max:366})}${field(input,'business.revenue','Przychód z poprzedniego roku (zł)',{step:.01})}${field(input,'business.income','Dochód z poprzedniego roku (zł)',{step:.01})}${field(input,'business.socialInCosts','Składki społeczne ujęte w kosztach (zł)',{step:.01})}${select(input,'business.tax','Opodatkowanie',[['normal','Dochód według właściwych zasad'],['lump','Ryczałt — dochód jako 50% przychodu']])}${field(input,'business.preferenceUsedMonths','Wykorzystane miesiące preferencyjnej podstawy (zwykle do 24)',{step:1,max:60})}${field(input,'business.monthsUsed','Miesiące Małego ZUS Plus w bieżącym 60-miesięcznym okresie od 2026 r.',{step:1,max:60})}</div>${check(input,'business.previousBusiness','Była wcześniejsza pozarolnicza działalność (także odpowiednia spółka)')}${check(input,'business.previousCEIDG','Wcześniejsza działalność obejmowała JDG / wspólnika spółki cywilnej (dla ulgi na start)')}${check(input,'business.formerEmployer','Działalność dla byłego pracodawcy w ustawowo wyłączającym zakresie')}${check(input,'business.parentalLeave','Rozpoczęcie działalności podczas urlopu wychowawczego')}${check(input,'business.activeLastYear','Działalność prowadzona w poprzednim roku')}${check(input,'business.otherExclusion','Występuje inne wyłączenie z ulgi (np. odpowiedni inny rodzaj działalności)')}<p class="field-help">Ulgi nie oznaczają automatycznego prawa do chorobowego. To podstawa składek, nie kwota zasiłku.</p></section>`;}
